```sql
/* Процент карт без силы (power IS NULL или '*'), которые на французском языке */
SELECT
    /* Доля французских карт среди карт без силы, в процентах */
    (COUNT(*) FILTER (WHERE fd."language" = 'French')::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS french_percentage
FROM foreign_data fd
WHERE fd."power" IS NULL OR fd."power" = '*';
```

```sql
/* Процент французских карт среди карт Story Spotlight */
SELECT
    /* Доля французских карт среди Story Spotlight, в процентах */
    (COUNT(CASE WHEN fd."language" = 'French' THEN 1 END)::numeric
     / NULLIF(COUNT(*), 0)) * 100 AS percentage
FROM cards c
JOIN foreign_data fd ON fd."uuid" = c."uuid"
WHERE c."isstoryspotlight" = 1;
