```sql
/* Доля супергероев-женщин среди "плохих" супергероев (alignment_id = 2, gender_id = 2) */
SELECT
    /* Процент = (женщины среди плохих / все плохие) * 100 */
    (SUM(CASE WHEN s."gender_id" = 2 THEN 1 ELSE 0 END)::numeric
     / COUNT(s."id")::numeric) * 100 AS female_percentage
FROM "superhero" s
WHERE s."alignment_id" = 2;
```

```sql
/* Доля героев Marvel Comics среди супергероев ростом 150-180 см */
SELECT
    /* Процент = (кол-во Marvel / общее кол-во) * 100 */
    SUM(CASE WHEN p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END)::numeric
    / COUNT(p."id") * 100 AS marvel_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
WHERE s."height_cm" BETWEEN 150 AND 180;
```

```sql
/* Доля супергероев с мировоззрением 'Bad' (действуют в своих интересах / по собственному кодексу) */
/* и количество таких героев, опубликованных Marvel Comics */
SELECT
    /* Процент "плохих" героев от общего числа */
    ROUND(
        100.0 * SUM(CASE WHEN a."alignment" = 'Bad' THEN 1 ELSE 0 END) / COUNT(s."id"),
        2
    ) AS bad_percentage,
    /* Количество "плохих" героев, опубликованных Marvel Comics */
    SUM(
        CASE WHEN a."alignment" = 'Bad' AND p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END
    ) AS bad_marvel_count
FROM "superhero" s
LEFT JOIN "alignment" a ON s."alignment_id" = a."id"
LEFT JOIN "publisher" p ON s."publisher_id" = p."id";
```

```sql
/* Считаем супергероев с отсутствующими данными о весе (weight_kg = 0 или NULL) */
/* Разница между числом героев с голубыми глазами (colour.id = 7) и без цвета глаз (colour.id = 1) */
SELECT
    SUM(CASE WHEN c.id = 7 THEN 1 ELSE 0 END)
    - SUM(CASE WHEN c.id = 1 THEN 1 ELSE 0 END) AS difference
FROM "superhero" s
JOIN "colour" c ON s."eye_colour_id" = c."id"
WHERE s."weight_kg" = 0 OR s."weight_kg" IS NULL;
```

